source='''def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0]); bg=max(set(x for row in grid for x in row), key=lambda c: sum(v==c for row in grid for v in row))
    seen=set()
    for r in range(h):
        for c in range(w):
            color=grid[r][c]
            if color==bg or (r,c) in seen: continue
            stack=[(r,c)]; seen.add((r,c)); cells=[]
            while stack:
                y,x=stack.pop(); cells.append((y,x))
                for p in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=p[0]<h and 0<=p[1]<w and p not in seen and grid[p[0]][p[1]]==color:
                        seen.add(p); stack.append(p)
            y0=min(y for y,x in cells); y1=max(y for y,x in cells); x0=min(x for y,x in cells); x1=max(x for y,x in cells)
            if y1-y0<2 or x1-x0<2: continue
            if all(grid[y][x]==color for x in range(x0,x1+1) for y in (y0,y1)) and all(grid[y][x]==color for y in (y0,y1) for x in range(x0,x1+1)):
                fill=2 if (y1-y0-1,x1-x0-1)==(2,2) else 7
                for y in range(y0+1,y1):
                    for x in range(x0+1,x1):
                        if grid[y][x]==bg: out[y][x]=fill
    return out
